const repair = s => /[\u00C2\u00C3\u00E2][\u0080-\u00BF]/.test(s) ? Buffer.from(s, 'latin1').toString('utf8') : s;

function htmlZuText(html) {
  return String(html || '')
    .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<a\b[^>]*?href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (z, url, text) => {
      const t = text.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      return t ? ` ${t} (${url}) ` : ` ${url} `;
    })
    .replace(/<(br|\/p|\/div|\/tr|\/h\d|\/li)[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const datum = m.date ? new Date(m.date) : new Date();
  const tag = datum.toISOString().slice(0, 10);
  const zeit = datum.toISOString().slice(11, 19).replace(/:/g, '');
  const absender = String(m.from && m.from.text ? m.from.text : m.from || '').toLowerCase();
  const quelle = absender.includes('stepstone') ? 'stepstone'
    : (absender.includes('indeed') ? 'indeed' : 'sonstige');
  const betreff = String(m.subject || 'ohne-betreff')
    .replace(/[^a-zA-Z0-9äöüÄÖÜß ._-]/g, '')
    .trim().slice(0, 60).replace(/ +/g, '-');
  const dateiname = `${tag}_${zeit}_${quelle}_${betreff}.md`;
  const plain = String(m.textPlain || m.text || '').trim();
  const html = m.textHtml || m.html || m.textAsHtml || '';
  const text = plain.length > 200 ? plain : (htmlZuText(html) || plain || '(kein Text)');
  const inhalt = [
    `# ${m.subject || '(ohne Betreff)'}`,
    ``,
    `- Von: ${m.from && m.from.text ? m.from.text : (m.from || '')}`,
    `- Datum: ${m.date || ''}`,
    `- Quelle: ${quelle}`,
    ``,
    `---`,
    ``,
    repair(text),
  ].join('\n');
  const binary = await this.helpers.prepareBinaryData(Buffer.from(inhalt, 'utf8'), dateiname, 'text/markdown');
  out.push({ json: { dateiname, quelle, betreff: m.subject || '' }, binary: { data: binary } });
}
return out;
